package dev.zomboidmelee.boxing;
import net.minecraft.world.phys.*;import net.minecraft.world.entity.Pose;import net.minecraft.core.BlockPos;
public class TunnelRegression28 {
 static int checks;static void ok(boolean x,String message){checks++;if(!x)throw new AssertionError(message);}
 static class Slider extends MovementChecks26.Local {Slider(){physics=new SlabRegression27.SlabWorld();}double height(){return forced==Pose.CROUCHING?1.5:pose==Pose.SWIMMING?.6:1.8;}public AABB getBoundingBox(){return new AABB(px-.3,py,pz-.3,px+.3,py+height(),pz+.3);}void move(){Vec3 v=getDeltaMovement();AABB box=new AABB(px+v.x-.3,py,pz+v.z-.3,px+v.x+.3,py+height(),pz+v.z+.3);horizontalCollision=!physics.noCollision(this,box);if(!horizontalCollision){px+=v.x;pz+=v.z;}physics.time++;}}
 public static void main(String[]args){Slider p=new Slider();p.physics.client=true;for(int z=1;z<=6;z++)p.physics.blocks.put(new BlockPos(0,1,z),new ParkourChecks25.Block(true));Slide20.clientTarget(p,0,1,.6,22);ok(p.height()<1,"slide must use collision lower than one block");ok(p.refreshes>0,"low collision dimensions applied immediately");for(int i=0;i<24;i++){Slide20.clientTick(p);p.move();}ok(p.pz>3,"slide moves through a one-block-high tunnel");ok(!Slide20.CLIENT.containsKey(p)&&p.forced==null&&p.pose==Pose.SWIMMING,"ending slide under ceiling releases ownership without standing inside blocks");double end=p.pz;p.velocity=new Vec3(0,0,.15);while(p.pz<7.5){p.move();Slide28.exit(p);}ok(p.pose==Pose.STANDING&&p.forced==null,"player stands automatically after leaving low tunnel");ok(p.pz>end,"leaving a tunnel needs no teleport");ok(Slide28.suppressSwim(p),"vanilla swimming recovery is suppressed after standing");p.physics.time+=30;ok(!Slide28.suppressSwim(p),"swimming recovery guard expires without sticking to the player");
 Slider tooLow=new Slider();tooLow.physics.client=true;tooLow.physics.blocks.put(new BlockPos(0,0,1),new SlabRegression27.Partial(.5,1));Slide20.clientTarget(tooLow,0,1,.6,22);tooLow.move();Slide20.clientTick(tooLow);ok(tooLow.pz==.5&&!Slide20.CLIENT.containsKey(tooLow),"half-block gap remains solid, no collision bypass");
 Slider ordinary=new Slider();ordinary.physics.client=true;Slide20.clientTarget(ordinary,0,1,.3,12);Slide20.clientStop(ordinary);ok(ordinary.pose==Pose.STANDING&&ordinary.forced==null,"unobstructed stop restores full-height pose");System.out.println("ONE_BLOCK_TUNNEL_LOW_DIMENSIONS_SAFE_EXIT_COLLISION_CHECKS="+checks);}
}
